'use strict';

// MODULES //

var ndarraylike2scalar = require( '@stdlib/ndarray/base/ndarraylike2scalar' );
var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var strided = require( '@stdlib/blas/ext/base/dsort2hp' ).ndarray;


// MAIN //

/**
* Simultaneously sorts two one-dimensional double-precision floating-point ndarrays based on the sort order of the first array using heapsort.
*
* ## Notes
*
* -   When the sort order is less than zero, the first input ndarray is sorted in **decreasing** order. When the sort order is greater than zero, the first input ndarray is sorted in **increasing** order. When the sort order is equal to zero, the input ndarrays are left unchanged. The second input ndarray is reordered based on the sort order of the first input ndarray.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing two one-dimensional input ndarrays and a zero-dimensional ndarray specifying the sort order
* @returns {Object} first input ndarray
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var ndarray2array = require( '@stdlib/ndarray/to-array' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
*
* var xbuf = new Float64Array( [ 1.0, -2.0, 3.0, -4.0 ] );
* var x = new ndarray( 'float64', xbuf, [ 4 ], [ 1 ], 0, 'row-major' );
*
* var ybuf = new Float64Array( [ 0.0, 1.0, 2.0, 3.0 ] );
* var y = new ndarray( 'float64', ybuf, [ 4 ], [ 1 ], 0, 'row-major' );
*
* var ord = scalar2ndarray( 1.0, {
*    'dtype': 'generic'
* });
*
* var out = dsort2hp( [ x, y, ord ] );
* // returns <ndarray>
*
* var arrX = ndarray2array( out );
* // returns [ -4.0, -2.0, 1.0, 3.0 ]
*
* var arrY = ndarray2array( y );
* // returns [ 3.0, 1.0, 0.0, 2.0 ]
*/
function dsort2hp( arrays ) {
	var ord;
	var x;
	var y;

	x = arrays[ 0 ];
	y = arrays[ 1 ];
	ord = ndarraylike2scalar( arrays[ 2 ] );
	strided( numelDimension( x, 0 ), ord, getData( x ), getStride( x, 0 ), getOffset( x ), getData( y ), getStride( y, 0 ), getOffset( y ) ); // eslint-disable-line max-len
	return x;
}


// EXPORTS //

module.exports = dsort2hp;
